class Solution:
    def deleteDuplicates(self,head):
        dummy=ListNode(0,head);previous=dummy
        while head:
            if head.next and head.val==head.next.val:
                value=head.val
                while head and head.val==value:head=head.next
                previous.next=head
            else:previous=head;head=head.next
        return dummy.next
